function findPiece(g,id=pieceId){const piece=g?.objects.find(o=>o.id===id||o.versions?.some(v=>v.id===id));return piece?previewPieceVersion(piece,previewVersions.get(piece.id)||(piece.id!==id?id:piece.assetId)):null;}
