 for(const g of map.values()){g.objects=groupPieceVersions(g.objects);const info=await store.getMeta('collection-info:'+g.id);if(info?.name)g.title=info.name;let c=await store.getMeta(coverKey(g.id));if(makeCovers&&!c&&g.photos.length){const blob=await makeLocalCover(g.photos,g.title);c={blob,kind:'photo-collage'};await store.setMeta(coverKey(g.id),c);}g.cover=url(c?.blob);g.coverKind=c?.kind;g.coverNeedsRefresh=Boolean(info?.name&&c?.kind==='generated'&&c.name!==info.name);}
