function updateCoverUI(){let button=root.querySelector('[data-action=cover]');const status=root.querySelector('#cover-status'),g=list().find(g=>g.id===tripId),pending=generationJobs.some(j=>(j.id===tripId||j.collectionId===tripId||g?.jobIds?.includes(j.id))&&j.coverStatus==='running');if(!button&&status&&g?.coverNeedsRefresh&&!demo){button=document.createElement('button');button.className='cover-generate';button.dataset.action='cover';status.before(button);}if(button){button.disabled=coverBusy.has(tripId)||pending;button.textContent=pending?'合集图正在生成…':coverBusy.has(tripId)?'正在提交合集图…':g?.coverNeedsRefresh?'按新名称重新生成合集图':'生成旅行合集图';button.setAttribute('aria-busy',String(button.disabled));}if(status)status.textContent=coverMessages.get(tripId)||(g?.coverNeedsRefresh?'改名已保存；点击重新生成会调用 AI 并消耗额度。':'');}
function renderCanvasProgress(){
 const host=root.querySelector('.collection-exhibit,.piece-stage,.create-inspiration,.home-viewport');if(!host||demo)return;
 const g=['collection','photo','piece'].includes(screen)?list().find(x=>x.id===tripId):null;
 let jobs=g?generationJobs.filter(j=>j.id===g.id||g.jobIds?.includes(j.id)||j.collectionId===g.id):generationJobs;
 if(screen==='create')jobs=jobs.filter(j=>j.id===createJobId);
 jobs=jobs.map(j=>{const group=g||groups.find(group=>group.id===j.collectionId||group.jobIds.includes(j.id));return group?{...j,name:group.title}:j;});
 const active=jobs.filter(j=>['queued','running','failed','partial','unavailable'].includes(j.status));jobs=active.length?active:jobs.slice(-1);
 let panel=host.querySelector('.canvas-generation');if(!panel){panel=document.createElement('section');panel.className='canvas-generation';panel.setAttribute('aria-label','画布制作进度');panel.setAttribute('aria-live','polite');host.append(panel);}
 const preparing=g&&coverBusy.has(g.id);
 panel.hidden=!jobs.length&&!preparing;
 const markup=(preparing?`<div class="canvas-job"><strong>${esc(g.title)} · 合集图</strong><p>正在准备照片并提交任务…</p></div>`:'')+jobs.map(j=>{const steps=j.steps||[],running=steps.find(s=>s.status==='running'),failed=steps.find(s=>s.status==='failed'),item=j.items?.find(i=>i.status==='running'),done=steps.filter(s=>s.status==='completed').length,state=j.status==='completed'?'制作完成':j.status==='queued'?'准备制作':j.status==='unavailable'?'查询已暂停':['failed','partial'].includes(j.status)?'需要处理':'正在制作';return `<article class="canvas-job" data-canvas-job="${esc(j.id)}"><div class="canvas-job-heading">${icon(j.status==='completed'?'check-circle':'clock')}<strong>${esc(j.name)}</strong><span>${state}</span></div><p>${esc(j.displayError||j.error||failed?.detail||running?.detail||(j.status==='completed'?`${j.assets?.length||0} 件3D作品已保存${j.cover?' · 合集图已完成':''}`:'任务已保存，等待开始'))}</p>${item?`<p class="canvas-job-item">${esc(item.title)}${Number.isFinite(item.progress?.percent)?` · 云端${item.progress.stage==='model'?'建模':'生图'} ${item.progress.percent}%`:''}</p>`:''}${steps.length?`<label class="canvas-job-meter">已完成 ${done} / ${steps.length} 个阶段<progress max="${steps.length}" value="${done}"></progress></label><details class="canvas-job-steps"><summary>查看制作步骤</summary><ol>${steps.map(s=>`<li data-phase="${esc(s.status)}">${icon(s.status==='completed'?'check-circle':'clock')}<span>${esc(s.detail==='等待执行'?s.title:s.detail)}</span><small>${{completed:'已完成',running:'进行中',failed:'失败',pending:'等待'}[s.status]||''}</small></li>`).join('')}</ol></details>`:''}</article>`;}).join('');
 const canCollapse=!preparing&&jobs.length>0&&jobs.every(j=>j.status==='completed'&&!j.error&&!j.coverError),key=jobs.map(j=>j.id).join('|'),collapsed=canCollapse&&collapsedCanvasJobs.has(key);
 panel.classList.toggle('is-collapsed',collapsed);
 const toggle=canCollapse?`<button class="canvas-collapse" data-collapse-canvas="${esc(key)}" aria-expanded="${!collapsed}" aria-label="${collapsed?'展开':'收起'}制作进度">${collapsed?'制作完成 · 展开':'收起'}</button>`:'';
 const content=toggle+(collapsed?'':markup);
 const openSteps=new Set([...panel.querySelectorAll('.canvas-job-steps[open]')].map(details=>details.closest('[data-canvas-job]')?.dataset.canvasJob));
 if(panel.innerHTML!==content)panel.innerHTML=content;
 if(!collapsed)for(const el of panel.querySelectorAll('[data-canvas-job]')){const source=[...taskStorage.querySelectorAll('.generation-job')].find(job=>job.querySelector('[data-job]')?.dataset.job===el.dataset.canvasJob);if(!source)continue;let controls=el.querySelector('.canvas-task-actions');if(!controls){controls=document.createElement('div');controls.className='canvas-task-actions';el.append(controls);}controls.replaceChildren(...[...source.children].filter(child=>child.matches('.generation-actions,.generation-error,.generation-item-status,[data-generation]')||child.querySelector('[data-generation]')).map(control=>control.cloneNode(true)));}
 for(const details of panel.querySelectorAll('.canvas-job-steps'))if(openSteps.has(details.closest('[data-canvas-job]')?.dataset.canvasJob))details.open=true;
}
