async function generateCover(){
 const g=list().find(g=>g.id===tripId);if(!g||demo||coverBusy.has(g.id))return;if(!generation){coverMessages.set(g.id,'制作服务正在加载，请稍后再试');updateCoverUI();return;}
 coverBusy.add(g.id);coverMessages.set(g.id,'正在检查合集图任务…');updateCoverUI();renderCanvasProgress();
 const request=async(path,body)=>{const response=await fetch(path,{...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(60000)});const result=await response.json();if(!response.ok)throw Object.assign(Error(result.error||'合集图任务暂不可用'),{status:response.status});return result;};
 try{
  const parent=g.coverNeedsRefresh?null:g.objects.find(o=>o.generationId&&!o.generationId.startsWith('sg-'))?.generationId;let current=null;
  if(parent)try{current=await request('/api/collection-jobs/'+encodeURIComponent(parent));}catch(error){if(![403,404].includes(error.status))throw error;}
  if(current){
   const draft=await store.getMeta('generation-input:'+parent);if(draft&&draft.collectionId!==g.id)await store.setMeta('generation-input:'+parent,{...draft,collectionId:g.id});
   if(!current.cover){coverMessages.set(g.id,'正在准备合集图素材…');updateCoverUI();await request(`/api/collection-jobs/${encodeURIComponent(parent)}/cover`,{...await makeCoverGuide(g.photos),name:g.title});}
   coverMessages.set(g.id,current.cover?'合集图已完成，正在同步到展厅…':'合集图任务已提交，画布将显示制作步骤');updateCoverUI();await generation.track(parent);
  }else{
   const coverJobKey='cover-job:'+g.id+(g.coverNeedsRefresh?':'+g.title:'');const id=await store.getMeta(coverJobKey)||crypto.randomUUID();await store.setMeta(coverJobKey,id);
   const cover=await makeCoverGuide(g.photos),photos=[];
   for(let i=0;i<g.photos.length;i++){const p=g.photos[i],image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('来源照片读取失败'));r.readAsDataURL(p.blob);});photos.push({id:'p'+(i+1),image});}
   const body={requestId:id,name:g.title,place:g.city==='待确认地点'?'':g.city,date:/^\d{4}-\d{2}-\d{2}$/.test(g.date)?g.date:'',story:g.story,style:'clay',memoryMode:'personal',photos,cover};
   await store.setMeta('generation-input:'+id,{...body,collectionId:g.id,replaceCover:g.coverNeedsRefresh,photos:g.photos});
   await request('/api/collection-cover',body);coverMessages.set(g.id,'合集图任务已提交，画布将显示制作步骤');updateCoverUI();await generation.track(id);
  }
  toast(coverMessages.get(g.id));
 }catch(error){const message=error.name==='TimeoutError'?'提交响应超时，任务编号已保留，请查看制作进度确认':error.message;coverMessages.set(g.id,message);toast(message);}
 finally{coverBusy.delete(g.id);updateCoverUI();renderCanvasProgress();}
}
