// The inline creation flow below is reused from the existing studio.
function addMemory(){if(creationPanel.innerHTML)return;if(saving){toast('正在保存，请稍候。');return;}uploadToken++;uploadPhotos=[];uploaded=false;creationPanel.innerHTML=`<h2 class="studio-create-title">制作工具</h2><div class="studio-tool-tabs"><button class="active" data-action="studio-create-tab">制作</button><button data-action="edit">布置</button></div><p class="upload-intro">放入照片和一句记忆，自动整理故事、生成纪念品，再摆进旅行世界。</p><label class="world-photo-drop" tabindex="0" role="button" aria-label="上传旅行照片">${icon('paperclip')}<strong>点击上传旅行照片</strong><span>JPEG、PNG、WebP · 1到9张</span><input name="photo" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden></label><div class="world-upload-assets"></div><label class="world-optional">合集名称 <span>选填</span><input name="trip-name" maxlength="60" placeholder="例如：广州毕业旅行"></label><fieldset class="world-mode"><legend>你想留下什么？</legend><label><input name="memory-mode" type="radio" value="personal" checked><span>我的旅行记忆<small>结合照片中的人物与重要物件</small></span></label><label><input name="memory-mode" type="radio" value="city"><span>城市与风景<small>只提取可见风景与物件</small></span></label></fieldset><label class="world-optional">说一句想记住的事 <span>选填</span><textarea name="note" rows="2" maxlength="1000" placeholder="例如：毕业前，和朋友一起走过珠江边"></textarea></label><label class="world-optional">旅行地点 <span>选填</span><input name="city" maxlength="40" placeholder="例如：广州"></label><label class="world-optional">旅行日期 <span>选填</span><input name="trip-date" type="date"></label><label class="world-optional">纪念品风格<select name="generation-style"><option value="clay">奶油黏土</option><option value="enamel">珐琅</option><option value="ceramic">陶瓷釉彩</option><option value="paper">复古拼贴</option><option value="wood">木雕</option></select></label><div class="world-upload-actions"><button class="primary" data-action="generate-upload" disabled>一键制作旅行合集</button><button class="secondary world-save-upload" data-action="save-upload" disabled>保存到画布</button></div><p class="upload-status" role="status">一键制作会调用 AI 与 Tripo，生成旅行合集图及最多3件3D纪念品，并消耗账户额度。也可以先只保存照片。</p>`;const style=creationPanel.querySelector('[name=generation-style]');style.setAttribute('aria-label','纪念品风格');style.insertAdjacentHTML('beforebegin','<div class="studio-style-options"><button class="studio-style-choice active" aria-pressed="true" data-action="style-clay"><i class="material-clay"></i>奶油黏土</button><button class="studio-style-choice" aria-pressed="false" data-action="style-enamel"><i class="material-enamel"></i>珐琅</button></div>');const extra=document.createElement('details');extra.className='studio-extra';extra.innerHTML='<summary>旅行信息与主体选择</summary>';extra.append(creationPanel.querySelector('.world-mode'));for(const name of ['trip-name','city','trip-date'])extra.append(creationPanel.querySelector('[name='+name+']').closest('label'));extra.append(style);creationPanel.querySelector('.world-upload-actions').before(extra);}
async function generateUpload(){if(saving||!uploadPhotos.length||!await ensureUserStore())return;saving=true;creationPanel.inert=true;const button=creationPanel.querySelector('[data-action=generate-upload]');button.disabled=true;try{if(!generation)throw Error('生成服务正在加载，请稍后重试');await generation.start({name:creationPanel.querySelector('[name=trip-name]').value.trim(),story:creationPanel.querySelector('[name=note]').value.trim(),place:creationPanel.querySelector('[name=city]').value.trim(),date:creationPanel.querySelector('[name=trip-date]').value,style:creationPanel.querySelector('[name=generation-style]').value,memoryMode:creationPanel.querySelector('[name=memory-mode]:checked').value,photos:uploadPhotos});uploaded=false;uploadPhotos=[];dialog.close();creationPanel.querySelector('[name=photo]').value='';toast('生成任务已保存，可以在画布查看制作进度。');creationPanel.querySelector('.upload-status').textContent='任务正在后台制作，关闭页面后仍会继续。';}catch(error){creationPanel.querySelector('.upload-status').textContent=error.message;button.disabled=false;}finally{saving=false;creationPanel.inert=false;if(!uploadPhotos.length){creationPanel.querySelector('[data-action=generate-upload]').disabled=true;creationPanel.querySelector('[data-action=save-upload]').disabled=true;}}}
async function compress(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw new Error('请上传10MB以内的JPEG、PNG或WebP');let b;try{b=await createImageBitmap(file);}catch{throw new Error('这张照片无法读取，请换一张');}try{if(b.width*b.height>24000000)throw new Error('照片像素过大，请先缩小');const s=Math.min(1,1024/Math.max(b.width,b.height)),c=document.createElement('canvas');c.width=Math.round(b.width*s);c.height=Math.round(b.height*s);c.getContext('2d').drawImage(b,0,0,c.width,c.height);const blob=await new Promise(r=>c.toBlob(r,'image/jpeg',.86));if(!blob)throw new Error('照片压缩失败');return {id:crypto.randomUUID(),blob,width:c.width,height:c.height};}finally{b.close();}}
async function saveUpload(){if(saving||!uploadPhotos.length||!await ensureUserStore())return;const button=creationPanel.querySelector('[data-action=save-upload]');if(!uploadPhotos.length||saving)return;saving=true;creationPanel.inert=true;button.disabled=true;try{const id=crypto.randomUUID(),mid=crypto.randomUUID(),now=Date.now(),date=creationPanel.querySelector('[name=trip-date]').value||new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date()),story=creationPanel.querySelector('[name=note]').value.trim(),city=creationPanel.querySelector('[name=city]').value.trim()||'待确认地点',mode=creationPanel.querySelector('[name=memory-mode]:checked').value,k={id,schemaVersion:1,title:creationPanel.querySelector('[name=trip-name]').value.trim()||(story?Array.from(story).slice(0,24).join(''):'新的一段旅行回忆'),city,dateStart:date,dateEnd:date,kind:'magnet',scope:'personal',participants:[{id:'me',name:'我'}],modelRef:'pending',memoryMode:mode,memoryIds:[mid],createdAt:now,updatedAt:now,origin:'user'},m={id:mid,keepsakeId:id,authorId:'me',date,placeName:city,story,photoIds:uploadPhotos.map(p=>p.id)};const ms=uploadPhotos.length>4?uploadPhotos.map((p,i)=>({...m,id:mid+'-'+i,photoIds:[p.id],story:i===0?story:''})):[m];k.memoryIds=ms.map(m=>m.id);await store.save({keepsake:k,memories:ms,photos:uploadPhotos});demo=false;uploaded=false;uploadPhotos=[];creationPanel.querySelector('[name=photo]').value='';creationPanel.querySelector('.world-upload-assets').innerHTML='';dialog.close();await readGroups();await store.setMeta('world-show-mine',true);location.hash='world/canvas';render();toast('旅行回忆已保存到本机，模型暂用占位图形表示。');}catch(e){creationPanel.querySelector('.upload-status').textContent=e.message;button.disabled=false;}finally{saving=false;creationPanel.inert=false;if(!uploadPhotos.length){creationPanel.querySelector('[data-action=generate-upload]').disabled=true;creationPanel.querySelector('[data-action=save-upload]').disabled=true;}}}

try{store=await openKeepsakeStore();layout=await store.getMeta('world-layout-v1')||layout;if(await store.getMeta('world-show-mine'))demo=false;await readGroups({makeCovers:false});if(!location.hash.startsWith('#world/'))history.replaceState(null,'','#world/canvas');addMemory();render();
 // Existing collections appear before old-library scanning and missing-cover rendering.
 if(!store.remote)void (async()=>{await importLegacyCabinet();await importShiguangCollections(store);await readGroups();render();})().catch(()=>toast('旧记录与封面暂未整理完成，已有收藏仍可使用。'));else if(groups.some(g=>!g.cover&&g.photos.length))void readGroups().then(render).catch(()=>toast('照片已保留，封面暂未整理完成。'));
 if(!accountInfo.enabled||accountInfo.user)generation=await initCollectionGeneration(store,async()=>{await readGroups();render();},{background:true});if(screen==='create'){const plan=JSON.parse(sessionStorage.getItem('lvzang-generation-context')||'null');if(plan){creationPanel.querySelector('[name=trip-name]').value=String(plan.name||'').slice(0,60);creationPanel.querySelector('[name=city]').value=String(plan.place||'').slice(0,40);creationPanel.querySelector('[name=trip-date]').value=String(plan.date||'');}sessionStorage.removeItem('lvzang-generation-context');}}catch(error){root.innerHTML='<div class="missing-trip"><h1>暂时无法打开收藏</h1><p>'+esc(error.message)+'</p><p>原记录已保留，请刷新重试。</p></div>';}
document.addEventListener('change',e=>{
 if(e.target.name==='piece-version'){const piece=findPiece(list().find(g=>g.id===tripId));if(!piece?.versions?.some(v=>v.id===e.target.value))return;previewVersions.set(piece.id,e.target.value);render();root.querySelector('[name=piece-version]')?.focus({preventScroll:true});}
 if(['compare-left','compare-right'].includes(e.target.name))void compareVersions(dialog.querySelector('[name=compare-left]').value,dialog.querySelector('[name=compare-right]').value,dialog.dataset.compareView).catch(error=>toast(error.message));
});
